              "maxLength": 2048,
              "minLength": 1,
              "format": "safe-url"
            }
          }
        }
      },
      "variant": {
        "type": "string",
        "enum": [
          "left",
          "center",
          "below"
        ],
        "maxLength": 16
      },
      "logo-url": {
        "type": "string",
        "maxLength": 2048,
        "format": "safe-url"
      },
      "logo-alt": {
        "type": "string",
        "maxLength": 160
      }
    }
  },
  "providerKey": null,
  "cache": {
    "scope": "public",
    "ttlSeconds": 3600,
    "varyBy": [
      "tenant",
      "locale",
      "release"
    ]
