e=\"shop\"] .wfcr-main{gap:20px}.wfcr-header[data-style=\"corporate\"] .wfcr-search{display:none}@media(max-width:1050px){.wfcr-main{flex-wrap:wrap;gap:12px;padding-block:14px}.wfcr-navigation{flex:1 1 auto}.wfcr-search{flex:1 0 100%;order:4}.wfcr-actions-zone{margin-left:auto}.wfcr-header .wf-primary-nav{position:relative}}@media(max-width:640px){.wfcr-inner{padding-inline:16px}.wfcr-main{gap:10px;min-height:60px}.wfcr-brand-zone{max-width:48%}.wfcr-navigation{flex:0 0 auto;margin-left:auto}.wfcr-actions-zone{flex:1 0 100%;margin-left:0}.wfcr-header .wfcr-actions-zone>.wf-slot{flex-wrap:wrap;justify-content:flex-start}.wfcr-utility>.wf-slot{justify-content:flex-start;flex-wrap:wrap}.wfcr-header .wf-nav-list{right:0;left:auto;width:min(88vw,400px);max-height:70vh;overflow-y:auto}.wfcr-header .wf-nav-children{position:static;box-shadow:none;width:100%}}\n.wfcr-header .wf-nav-list .wf-nav-children :is(a,button){color:var(--wf-color-text)}.wfcr-header .wf-nav-list .wf-nav-children :is(a,button):is(:hover,:focus-visible){color:var(--wf-color-text);background:var(--wf-color-background)}.wfcr-header .wf-nav-list :focus-visible{outline:2px solid var(--wf-color-text);outline-offset:2px}@media(max-width:780px){.wfcr-header .wf-nav-list{background:var(--wf-color-surface);color:var(--wf-color-text)}.wfcr-header .wf-nav-list>.wf-nav-item>:is(a,button):is(:hover,:focus-visible){color:var(--wf-color-text);background:var(--wf-color-background)}}"
