retraži proizvode…" autocomplete="off"></label><label data-wf-category-label><span class="wf-visually-hidden">Kategorija</span><select data-wf-category><option value="all">Sve kategorije</option></select></label><button type="button" data-wf-apply-search>Primeni</button></form><p class="wf-catalog__offers-status" data-wf-offers-status role="status" hidden></p><div class="wf-catalog__chips" data-wf-chips></div><button type="button" class="wf-catalog__filters-toggle" data-wf-filters-toggle>Filteri</button><div class="wf-catalog__body"><aside class="wf-catalog__filters" data-wf-filters aria-label="Filteri"></aside><div class="wf-catalog__main"><p class="wf-catalog__status" data-wf-status role="status"></p><div class="wf-catalog__results" data-wf-results></div><nav class="wf-catalog__pagination" data-wf-pagination aria-label="Stranice kataloga"></nav></div></div></section>",
