k",function(){show(image.url,data.name||"");thumbs.querySelectorAll("button").forEach(function(other){other.removeAttribute("aria-current");});button.setAttribute("aria-current","true");});thumbs.appendChild(button);});gallery.appendChild(thumbs);}specBody.innerHTML="";var rows=Array.isArray(data.characteristics)?data.characteristics:[];rows.forEach(function(row){var tr=el("tr");tr.appendChild(el("th","",row.name||""));tr.appendChild(el("td","",row.value||""));specBody.appendChild(tr);});specs.hidden=!rows.length;while(relatedGrid.firstChild)relatedGrid.removeChild(relatedGrid.firstChild);var others=Array.isArray(data.related)?data.related:[];others.forEach(function(item){if(!item||!item.id)return;var card=el("a","wf-detail__card");card.setAttribute("data-wf-item-id",String(item.id));card.href=detailUrl(item.id);var image=el("img");image.src=item["image-url"]||"/commonAssets/Images/coming_soon_transparent.png";image.alt=item.name||"";image.loading="lazy";card.appendChild(image);var body=el("span","wf-detail__card-body");if(item.brand)body.appendChild(el("span","wf-detail__card-brand",item.brand));body.appendChild(el("strong","",item.name||item.id));var regular=el("del"),actual=el("span","",money(item.price,item.currency)),discount=el("small");regular.setAttribute("data-wf-regular-price","");regular.hidden=true;actual.setAttribute("data-wf-price","");actual.hidden=root.dataset.showPrice==="false";discount.setAttribute("data-wf-discount","");discount.hidden=true;body.appendChild(regular);body.appendChild(actual);body.appendChild(discount);card.appendChild(body);relatedGrid.appendChild(card);});related.hidden=!relatedGrid.children.length;scheduleOffers([data].concat(others));}
function load(){cancelOffers();var id=productId();if(!id){showStatus("Proizvod nije izabran.",true);return;}var request=requestId();pendingId=request;status.textContent="Učitavanje…";status.removeAttribute("data-error");if(panel)panel.hidden=true;var input={id:id};if(host.dataset.wfCatalogBridge==="true"){window.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",input:input,requestId:request},"*");return;}var url=new URL(host.dataset.wfProviderUrl,window.location.href);url.searchParams.set("wf_input",encode(input));fetch(url.toString(),{credentials:"same-origin",headers:{Accept:"application/json"}}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.json();}).then(function(payload){if(pendingId!==request)return;render(payload.data!==undefined?payload.data:payload);}).catch(function(error){if(pendingId!==request)return;showStatus(error&&error.message?error.message:"Proizvod trenutno nije dostupan.",true);});}
