  "scripts": [
    {
      "name": "front-auth.js",
      "content": "/*
 * Front login. Webfront i samostalna strana zovu isti poziv:
 *   ElastycFrontAuth.init({ host: '#login' });
 * Kredencijali Google/Microsoft ostaju na serveru (Integracije).
 * Ovaj fajl samo crta formu i vodi na /incKomponente/auth/.
 */
(function (global) {
  'use strict';

  var PROVIDERS = {
    google: 'Nastavi sa Google',
    microsoft: 'Nastavi sa Microsoft'
  };

  var ERRORS = {
    denied: 'Prijava je otkazana.',
    state: 'Prijava je istekla. Pokušajte ponovo.',
    email: 'Email nije potvrđen kod provajdera.',
    unavailable: 'Prijava trenutno nije dostupna.',
    linked: 'Ovaj nalog je već povezan sa drugim korisnikom.',
    credentials: 'Korisničko ime ili lozinka nisu tačni.',
    pending: 'Nalog čeka potvrdu. Prijava još nije otvorena.'
  };

  var mounts = typeof WeakMap === 'function' ? new WeakMap() : null;
  var mountList = [];
  var authQuery = null;

  function text(value) {
    return value == null ? '' : String(value);
  }

  function errorText(code) {
    var key = text(code);
    return ERRORS[key] || ERRORS.unavailable;
  }

  function endpoints(options) {
    var base = text(options && options.apiBase).replace(/\/$/, '');
    return {
      config: base + '/incKomponente/auth/config.php',
      login: base + '/incKomponente/auth/login.php',
      start: base + '/incKomponente/auth/start.php',
      pending: base + '/incKomponente/auth/pending.php',
      register: base + '/incKomponente/auth/register.php',
      logout: base + '/incKomponente/auth/logout.php'
    };
  }

  function resolveHost(host) {
    if (!host) throw new Error('ElastycFrontAuth.init: host je obavezan');
    if (typeof host === 'string') {
      var found = global.document && global.document.querySelector(host);
      if (!found) throw new Error('ElastycFrontAuth.init: host nije nađen');
      return found;
    }
    if (host.nodeType === 1) return host;
    throw new Error('ElastycFrontAuth.init: host nije element');
  }

  function safeReturn(value) {
    var loc = global.location;
    var fallback = '/';
    if (loc) {
      var current = new URL(loc.href);
      current.searchParams.delete('elastyc_auth');
      current.searchParams.delete('elastyc_auth_error');
      fallback = current.pathname + current.search;
    }
    if (!value || !loc) return fallback;
    try {
      var url = new URL(text(value), loc.origin);
      if (url.origin !== loc.origin) return fallback;
      url.searchParams.delete('elastyc_auth');
      url.searchParams.delete('elastyc_auth_error');
      return url.pathname + url.search;
    } catch (e) {
      return fallback;
    }
  }

  function consumeAuthQuery() {
    if (authQuery) return authQuery;
    authQuery = { status: '', code: '' };
    if (!global.location) return authQuery;
    var url = new URL(global.location.href);
    authQuery.status = url.searchParams.get('elastyc_auth') || '';
    authQuery.code = url.searchParams.get('elastyc_auth_error') || '';
    if (authQuery.status || authQuery.code) {
      url.searchParams.delete('elastyc_auth');
      url.searchParams.delete('elastyc_auth_error');
      if (global.history && global.history.replaceState) {
        global.history.replaceState(null, '', url.pathname + url.search + url.hash);
      }
    }
    return authQuery;
  }

  function fetchJson(url, mount, body) {
    var headers = { Accept: 'application/json' };
    var opts = {
      method: body ? 'POST' : 'GET',
      credentials: 'same-origin',
      headers: headers
    };
    if (mount && mount.controller) opts.signal = mount.controller.signal;
    if (body) {
      headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    return global.fetch(url, opts).then(function (res) {
      return res.json().catch(function () {
        return {};
      }).then(function (data) {
        data = data && typeof data === 'object' ? data : {};
        if (!res.ok) data.ok = false;
        if (!data.error && !res.ok) data.error = 'unavailable';
        return data;
      });
    }).catch(function (err) {
      if (err && err.name === 'AbortError') throw err;
      return { ok: false, error: 'unavailable' };
    });
  }

  function el(tag, attrs, children) {
    var node = global.document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (key) {
        if (attrs[key] == null || attrs[key] === false) return;
        if (key === 'className') node.className = attrs[key];
        else if (key === 'text') node.textContent = attrs[key];
        else node.setAttribute(key, attrs[key] === true ? '' : attrs[key]);
      });
    }
    (children || []).forEach(function (child) {
      if (child) node.appendChild(child);
    });
    return node;
  }

  function field(id, label, input) {
    var caption = el('span', { text: label });
    input.id = id;
    return el('label', { className: 'efa-field' }, [caption, input]);
  }

  function inputEl(type, name, autocomplete, value) {
    return el('input', {
      type: type,
      name: name,
      autocomplete: autocomplete,
      value: value || null,
      required: type !== 'tel'
    });
  }

  function clear(mount) {
    var root = mount.root;
    while (root.firstChild) root.removeChild(root.firstChild);
  }

  function showError(mount, code) {
    if (!code) return;
    var box = mount.root.querySelector('.efa-error');
    if (!box) return;
    box.hidden = false;
    box.textContent = errorText(code);
  }

  function setBusy(mount, busy) {
    mount.host.setAttribute('aria-busy', busy ? 'true' : 'false');
    var controls = mount.root.querySelectorAll('button, input');
    for (var i = 0; i < controls.length; i++) controls[i].disabled = !!busy;
  }

  function providerList(data) {
    var raw = data && data.providers;
    var out = [];
    if (!raw || !raw.length) return out;
    raw.forEach(function (item) {
      var id = typeof item === 'string' ? item : item && item.id;
      if (!PROVIDERS[id]) return;
      if (out.indexOf(id) !== -1) return;
      out.push(id);
    });
    return out;
  }

  function paintLogin(mount, data, notice) {
    clear(mount);
    var idBase = mount.idBase;
    var title = el('h2', { className: 'efa-title', text: 'Prijava' });
    var error = el('p', { className: 'efa-error', role: 'alert' });
    error.hidden = true;
    var form = el('form', { className: 'efa-form', novalidate: true });
    var username = inputEl('text', 'username', 'username');
    var password = inputEl('password', 'password', 'current-password');
    password.required = true;
    username.required = true;
    form.appendChild(field(idBase + '-user', 'Korisničko ime', username));
    form.appendChild(field(idBase + '-pass', 'Lozinka', password));
    form.appendChild(el('button', { className: 'efa-primary', type: 'submit', text: 'Prijavi se' }));
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      if (!username.value || !password.value) {
        showError(mount, 'credentials');
        return;
      }
      setBusy(mount, true);
      fetchJson(mount.ep.login, mount, {
        username: username.value,
        password: password.value
      }).then(function (res) {
        setBusy(mount, false);
        if (res.ok && res.user) finish(mount, res.user);
        else showError(mount, res.error || 'credentials');
      });
    });

    mount.root.appendChild(title);
    mount.root.appendChild(error);
    if (data.password !== false) mount.root.appendChild(form);

    var providers = providerList(data);
    if (providers.length && data.password !== false) {
      mount.root.appendChild(el('p', { className: 'efa-or', text: 'ili' }));
    }
    providers.forEach(function (id) {
      var button = el('button', {
        className: 'efa-provider',
        type: 'button',
        text: PROVIDERS[id]
      });
      button.addEventListener('click', function () {
        var url = new URL(mount.ep.start, global.location.href);
        url.searchParams.set('provider', id);
        url.searchParams.set('return', mount.returnUrl);
        global.location.assign(url.href);
      });
      mount.root.appendChild(button);
    });

    if (mount.options.register !== false && data.register !== false) {
      var link = el('button', { className: 'efa-link', type: 'button', text: 'Napravite nalog' });
      link.addEventListener('click', function () {
        paintRegister(mount, data, null);
      });
      mount.root.appendChild(link);
    }
    if (!providers.length && data.password === false) {
      showError(mount, 'unavailable');
    }
    if (notice) showError(mount, notice);
  }

  function paintRegister(mount, data, profile) {
    clear(mount);
    var pending = !!profile;
    var idBase = mount.idBase;
    var title = el('h2', {
      className: 'efa-title',
      text: pending ? 'Potvrdi nalog' : 'Registracija'
    });
    var error = el('p', { className: 'efa-error', role: 'alert' });
    error.hidden = true;
    var lead = pending
      ? el('p', { className: 'efa-lead', text: 'Email je proveren. Potvrdi podatke da se nalog otvori.' })
      : null;
    var form = el('form', { className: 'efa-form' });
    var given = inputEl('text', 'givenName', 'given-name', profile && profile.givenName);
    var family = inputEl('text', 'familyName', 'family-name', profile && profile.familyName);
    var email = inputEl('email', 'email', 'email', profile && profile.email);
    var phone = inputEl('tel', 'phone', 'tel');
    phone.required = false;
    if (pending) {
      email.readOnly = true;
      email.setAttribute('aria-readonly', 'true');
    }
    var legal = el('input', { type: 'checkbox', name: 'legalEntity' });
    var legalRow = el('label', { className: 'efa-check' }, [
      legal,
      el('span', { text: 'Pravno lice' })
    ]);
    form.appendChild(field(idBase + '-given', 'Ime', given));
    form.appendChild(field(idBase + '-family', 'Prezime', family));
    form.appendChild(field(idBase + '-email', 'Email', email));
    form.appendChild(field(idBase + '-phone', 'Telefon', phone));
    if (!pending) {
      var password = inputEl('password', 'password', 'new-password');
      form.appendChild(field(idBase + '-newpass', 'Lozinka', password));
    }
    form.appendChild(legalRow);
    form.appendChild(el('button', {
      className: 'efa-primary',
      type: 'submit',
      text: pending ? 'Potvrdi' : 'Registruj se'
    }));
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var passwordInput = form.querySelector('input[name="password"]');
      if (!given.value || !family.value || !email.value || (!pending && passwordInput && !passwordInput.value)) {
        error.textContent = 'Popunite obavezna polja.';
        error.hidden = false;
        return;
      }
      setBusy(mount, true);
      fetchJson(mount.ep.register, mount, {
        mode: pending ? 'pending' : 'register',
        givenName: given.value,
        familyName: family.value,
        email: email.value,
        phone: phone.value,
        password: passwordInput ? passwordInput.value : '',
        legalEntity: !!legal.checked
      }).then(function (res) {
        setBusy(mount, false);
        if (res.ok && res.user) finish(mount, res.user);
        else if (res.ok) paintMessage(mount, 'Zahtev je sačuvan. Prijava se otvara kad nalog bude potvrđen.');
        else showError(mount, res.error || 'unavailable');
      });
    });

    mount.root.appendChild(title);
    if (lead) mount.root.appendChild(lead);
    mount.root.appendChild(error);
    mount.root.appendChild(form);

    if (!pending && data) {
      var providers = providerList(data);
      providers.forEach(function (id) {
        var button = el('button', {
          className: 'efa-provider',
          type: 'button',
          text: PROVIDERS[id]
        });
        button.addEventListener('click', function () {
          var url = new URL(mount.ep.start, global.location.href);
          url.searchParams.set('provider', id);
          url.searchParams.set('return', mount.returnUrl);
          global.location.assign(url.href);
        });
        mount.root.appendChild(button);
      });
    }

    var back = el('button', { className: 'efa-link', type: 'button', text: 'Već imate nalog? Prijavite se' });
    back.addEventListener('click', function () {
      paintLogin(mount, data || { password: true, register: true, providers: [] }, '');
    });
    mount.root.appendChild(back);
  }

  function paintMessage(mount, message) {
    clear(mount);
    mount.root.appendChild(el('h2', { className: 'efa-title', text: 'Nalog' }));
    mount.root.appendChild(el('p', { className: 'efa-lead', text: message }));
  }

  function paintSession(mount, user) {
    clear(mount);
    var name = text(user.name || user.userid || '');
    mount.root.appendChild(el('h2', { className: 'efa-title', text: 'Nalog' }));
    mount.root.appendChild(el('p', { className: 'efa-lead', text: name ? ('Prijavljeni ste kao ' + name + '.') : 'Prijavljeni ste.' }));
    var button = el('button', { className: 'efa-provider', type: 'button', text: 'Odjavi se' });
    button.addEventListener('click', function () {
      setBusy(mount, true);
      fetchJson(mount.ep.logout, mount, {}).then(function () {
        setBusy(mount, false);
        paintLogin(mount, { password: true, register: true, providers: providerList(mount.config) }, '');
        reloadConfig(mount);
      });
    });
    mount.root.appendChild(button);
  }

  function finish(mount, user) {
    if (typeof mount.options.onSuccess === 'function') mount.options.onSuccess(user);
    else paintSession(mount, user);
  }

  function reloadConfig(mount) {
    return fetchJson(mount.ep.config, mount).then(function (data) {
      mount.config = data && data.ok !== false ? data : { password: true, register: true, providers: [] };
      return mount.config;
    });
  }

  function boot(mount) {
    if (mount.controller) mount.controller.abort();
    var controller = new AbortController();
    mount.controller = controller;
    var query = consumeAuthQuery();
    clear(mount);
    mount.root.appendChild(el('p', { className: 'efa-lead', text: 'Učitavanje…' }));
    var pendingPromise = query.status === 'pending'
      ? fetchJson(mount.ep.pending, mount)
      : Promise.resolve(null);
    Promise.all([fetchJson(mount.ep.config, mount), pendingPromise]).then(function (pair) {
      if (mount.controller !== controller) return;
      var data = pair[0] || {};
      var pending = pair[1];
      if (data.ok === false && !data.providers && data.password == null) {
        clear(mount);
        mount.root.appendChild(el('p', { className: 'efa-error', role: 'alert', text: errorText(data.error) }));
        return;
      }
      mount.config = data;
      if (query.status === 'ok' && data.user) {
        finish(mount, data.user);
        return;
      }
      if (query.status === 'pending' && pending && pending.ok && pending.profile) {
        paintRegister(mount, data, pending.profile);
        return;
      }
      if (query.status === 'pending') {
        paintLogin(mount, data, 'state');
        return;
      }
      if (data.user && query.status !== 'error') {
        finish(mount, data.user);
        return;
      }
      if (mount.options.mode === 'register') paintRegister(mount, data, null);
      else paintLogin(mount, data, query.status === 'error' ? (query.code || 'unavailable') : '');
    }).catch(function (err) {
      if (mount.controller !== controller) return;
      if (err && err.name === 'AbortError') return;
      clear(mount);
      mount.root.appendChild(el('p', { className: 'efa-error', role: 'alert', text: errorText('unavailable') }));
    });
  }

  function destroyMount(mount) {
    if (!mount) return;
    if (mount.controller) mount.controller.abort();
    if (mount.root && mount.root.parentNode) mount.root.parentNode.removeChild(mount.root);
    mount.host.removeAttribute('aria-busy');
    mount.host.removeAttribute('data-elastyc-front-auth');
    if (mount.host.classList) mount.host.classList.remove('elastyc-front-auth');
    if (mounts) mounts.delete(mount.host);
    mountList = mountList.filter(function (item) { return item !== mount; });
  }

  function init(options) {
    options = options || {};
    var host = resolveHost(options.host);
    var previous = mounts ? mounts.get(host) : null;
    if (!previous) {
      for (var i = 0; i < mountList.length; i++) {
        if (mountList[i].host === host) previous = mountList[i];
      }
    }
    if (previous) destroyMount(previous);

    var mount = {
      host: host,
      options: options,
      ep: endpoints(options),
      returnUrl: safeReturn(options.returnUrl),
      controller: null,
      idBase: 'efa' + (mountList.length + 1),
      root: el('div', { className: 'efa-root' }),
      config: null
    };
    host.classList.add('elastyc-front-auth');
    host.setAttribute('data-elastyc-front-auth', '');
    host.appendChild(mount.root);
    if (mounts) mounts.set(host, mount);
    mountList.push(mount);
    boot(mount);
    return {
      destroy: function () { destroyMount(mount); },
      reload: function () { boot(mount); }
    };
  }

  function session(options) {
    var ep = endpoints(options);
    return fetchJson(ep.config, null).then(function (data) {
      if (data && data.ok === false && !data.user) return null;
      return data && data.user ? data.user : null;
    });
  }

  function logout(options) {
    var ep = endpoints(options);
    return fetchJson(ep.logout, null, {}).then(function (data) {
      return !!(data && data.ok !== false);
    });
  }

  global.ElastycFrontAuth = {
    init: init,
    destroy: function (host) {
      var node = resolveHost(host);
      var mount = mounts ? mounts.get(node) : null;
      if (!mount) {
        for (var i = 0; i < mountList.length; i++) {
          if (mountList[i].host === node) mount = mountList[i];
        }
      }
      destroyMount(mount);
    },
    session: session,
    logout: logout
  };
})(typeof window !== 'undefined' ? window : this);
