  "htmlContent": "<section class="wf-help-desk wf-hd-cards" aria-label="{{setting:title}}">
    <section data-hd-overview aria-label="Zahtevi">
        <div class="wf-hd-toolbar">
            <h1 class="wf-hd-title">{{setting:title}}</h1>
            <div class="wf-hd-scope" role="group" aria-label="Prikaži zahteve">
                <button type="button" data-hd-scope="open" aria-pressed="true">Otvoreni</button>
                <button type="button" data-hd-scope="all" aria-pressed="false">Svi</button>
            </div>
            <label class="wf-hd-filter">Status
                <select data-hd-status><option value="">Svi statusi</option></select>
            </label>
            <button type="button" class="wf-hd-primary" data-hd-new hidden>Novi predmet</button>
        </div>
        <p data-hd-feedback role="status" class="wf-hd-feedback">Učitavanje zahteva…</p>
        <button type="button" data-hd-retry hidden>Pokušaj ponovo</button>
        <ul class="wf-hd-list" aria-label="Lista zahteva" data-hd-list></ul>
        <nav class="wf-hd-pagination" aria-label="Strane zahteva" data-hd-pagination hidden>
            <button type="button" data-hd-previous>Prethodna</button>
            <button type="button" data-hd-next>Sledeća</button>
        </nav>
    </section>
    <section class="wf-hd-detail" data-hd-detail aria-label="Predmet i komunikacija" hidden>
        <button type="button" data-hd-back>← Nazad na zahteve</button>
        <div data-hd-thread aria-live="polite"></div>
    </section>
    <section class="wf-hd-create" data-hd-create aria-label="Novi predmet" hidden>
        <button type="button" data-hd-cancel>← Nazad na zahteve</button>
        {{slot:new-case}}
    </section>
</section>
