        "default": "Help Desk"
      }
    },
    "required": [
      "title"
    ]
  },
  "providerKey": "help-desk-cases",
  "cache": {
    "scope": "none",
    "ttlSeconds": 0,
    "varyBy": []
  },
  "access": {
    "visibility": "authenticated",
    "permissions": []
  },
  "seo": {
    "mode": "none"
  },
  "slots": [
    "new-case"
  ]
}

