{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "help-desk",
  "label": "Help Desk",
  "category": "account",
  "renderMode": "client-data",
  "targets": [
    "web"
  ],
  "htmlContent": "<section class="wf-help-desk wf-hd-cards" aria-label="{{setting:title}}">
    <section data-hd-overview class="wf-hd-overview" aria-label="{{setting:hd-requests}}">
        <aside class="wf-hd-filters" aria-label="Filteri">
            <details data-hd-filters open>
                <summary data-hd-copy="filters">Filteri</summary>
                <div class="wf-hd-facets">
                    <div class="wf-hd-scope" role="group" aria-label="{{setting:hd-scope}}">
                        <button type="button" data-hd-scope="open" aria-pressed="true">{{setting:hd-open}}</button>
                        <button type="button" data-hd-scope="all" aria-pressed="false">{{setting:hd-all}}</button>
                    </div>
                    <fieldset>
                        <legend data-hd-copy="status">Status</legend>
                        <div data-hd-options="statuses"></div>
                    </fieldset>
                    <fieldset>
                        <legend data-hd-copy="type">Tip zahteva</legend>
                        <div data-hd-options="request-types"></div>
                    </fieldset>
                    <button type="button" data-hd-clear hidden data-hd-copy="clear">Očisti filtere</button>
                </div>
            </details>
        </aside>
        <div class="wf-hd-results">
            <div class="wf-hd-heading">
                <div>
                    <h1 class="wf-hd-title">{{setting:title}}</h1>
                    <p data-hd-feedback role="status" class="wf-hd-feedback">{{setting:hd-loading}}</p>
                </div>
                <button type="button" class="wf-hd-primary" data-hd-new hidden>{{setting:hd-new}}</button>
            </div>
            <button type="button" data-hd-retry hidden>{{setting:hd-retry}}</button>
            <ul class="wf-hd-list" aria-label="{{setting:hd-list}}" data-hd-list></ul>
            <nav class="wf-hd-pagination" aria-label="{{setting:hd-pages}}" data-hd-pagination hidden>
                <button type="button" data-hd-previous>{{setting:hd-previous}}</button>
                <button type="button" data-hd-next>{{setting:hd-next}}</button>
            </nav>
        </div>
    </section>
    <section class="wf-hd-detail" data-hd-detail aria-label="{{setting:hd-detail}}" hidden>
        <button type="button" data-hd-back>← {{setting:hd-back}}</button>
        <div data-hd-thread aria-live="polite"></div>
    </section>
    <section class="wf-hd-create" data-hd-create aria-label="{{setting:hd-new}}" hidden>
        <button type="button" data-hd-cancel>← {{setting:hd-back}}</button>
        {{slot:new-case}}
    </section>
</section>
",
  "styles": [
    {
      "name": "help-desk.css",
      "content": ".wf-hd-cards {
    --hd-surface: var(--main-background1, var(--wf-color-surface, light-dark(#fff, #101a2b)));
    --hd-raised: var(--main-background2, var(--wf-color-background, light-dark(#f3f6fa, #162235)));
    --hd-text: var(--main-font-color, var(--wf-color-text, light-dark(#15253a, #e5edf8)));
    --hd-muted: var(--main-font-color-light, var(--wf-color-muted, light-dark(#4e6075, #b3c3d7)));
